  finderC.width = w; finderC.height = h;
  const g = finderC.getContext('2d'), x0 = (w - fw) / 2, y0 = (h - fh) / 2;
  g.fillStyle = g.createPattern(UI.leather, 'repeat'); g.fillRect(0, 0, w, h);
  g.globalCompositeOperation = 'multiply'; g.fillStyle = '#3a302a'; g.fillRect(0, 0, w, h); g.globalCompositeOperation = 'source-over';
