  g.strokeStyle = 'rgba(210,205,192,.75)'; g.lineWidth = 2; g.strokeRect(x0 - 2, y0 - 2, fw + 4, fh + 4);
  g.strokeStyle = 'rgba(40,40,50,.9)'; g.lineWidth = 2; g.strokeRect(x0 - 5, y0 - 5, fw + 10, fh + 10);
  g.strokeStyle = 'rgba(240,230,210,.2)'; g.lineWidth = 1;
