  $('doneBar').classList.toggle('show', full && !state.raised);
  $('bDevelop').hidden = state.photos.length === 0 || state.raised || full;
  $('bDevelop').classList.toggle('pulse', state.plates === 0 || (state.columnDone && state.photos.length > 0));
