  const clone = slot.cloneNode(true); clone.removeAttribute('id'); clone.querySelector('img').removeAttribute('id');
  clone.classList.remove('slot'); clone.style.cssText = `position:absolute;left:${sr.left}px;top:${sr.top}px;width:${sr.width}px;margin:0;z-index:10;transform-origin:50% 50%;opacity:0;`;
